215	export function extractIdsFromResponse(result: SendMessageResult): {
216	  contextId?: string;
217	  taskId?: string;
218	  clearTaskId?: boolean;
219	} {
220	  let contextId: string | undefined;
221	  let taskId: string | undefined;
222	  let clearTaskId = false;
223	
224	  if ('kind' in result) {
225	    const kind = result.kind;
226	    if (kind === 'message' || kind === 'artifact-update') {
227	      taskId = result.taskId;
228	      contextId = result.contextId;
229	    } else if (kind === 'task') {
230	      taskId = result.id;
231	      contextId = result.contextId;
232	      if (isTerminalState(result.status?.state)) {
