47	      }`;
48	      debugLogger.log('ERROR', errorMessage);
49	      throw new Error(errorMessage);
50	    }
51	  }
52	
53	  async shouldRetryWithHeaders(
54	    _response: unknown,
55	  ): Promise<Record<string, string> | undefined> {
56	    // For ADC, we usually just re-fetch the token if needed.
